  ('economia-empresarial', 'Economía Empresarial', 'Negocios', '#4527A0', 'Aplica la economía a las decisiones de la empresa: demanda, costos, mercados, precios, estrategia competitiva, entorno macroeconómico y riesgo.', 89900, 5, '[{"title": "Banco de la República", "publisher": "Banco de la República de Colombia", "url": "https://www.banrep.gov.co/es", "use": "Indicadores económicos y financieros"}, {"title": "DANE", "publisher": "Departamento Administrativo Nacional de Estadística", "url": "https://www.dane.gov.co/", "use": "Estadísticas oficiales de Colombia"}, {"title": "Superintendencia de Sociedades", "publisher": "Gobierno de Colombia", "url": "https://www.supersociedades.gov.co/", "use": "Sociedades y empresas en Colombia"}]'::jsonb, null),
  ('gestion-de-operaciones', 'Gestión de Operaciones', 'Negocios', '#6D4C41', 'Dirige la operación de bienes y servicios: estrategia de operaciones, procesos, capacidad, planeación, calidad, lean, servicios y cadena de suministro.', 89900, 5, '[{"title": "Familia ISO 9000 – Gestión de la calidad", "publisher": "ISO", "url": "https://www.iso.org/iso-9001-quality-management.html", "use": "Sistemas de gestión de calidad"}, {"title": "MIT OpenCourseWare", "publisher": "Massachusetts Institute of Technology", "url": "https://ocw.mit.edu/", "use": "Cursos universitarios gratuitos de ingeniería"}]'::jsonb, null),
