  ('medicina', 'Medicina (Fundamentos)', 'Salud', '#C62828', 'Recorre las bases de la medicina: anatomía, fisiología, patología, farmacología, semiología, especialidades y salud pública. Curso formativo: no habilita para el ejercicio profesional.', 89900, 5, '[{"title": "Organización Mundial de la Salud", "publisher": "OMS", "url": "https://www.who.int/es", "use": "Información de salud mundial"}, {"title": "Ministerio de Salud y Protección Social", "publisher": "Gobierno de Colombia", "url": "https://www.minsalud.gov.co/", "use": "Normas y programas de salud en Colombia"}, {"title": "MedlinePlus en español", "publisher": "Biblioteca Nacional de Medicina de EE. UU.", "url": "https://medlineplus.gov/spanish/", "use": "Información de salud para pacientes"}]'::jsonb, null),
  ('enfermeria', 'Enfermería (Fundamentos)', 'Salud', '#D81B60', 'Conoce el cuidado de enfermería: proceso de atención, procedimientos básicos, cuidado por ciclo vital, seguridad del paciente y gestión del cuidado. Curso formativo: no habilita para el ejercicio profesional.', 89900, 5, '[{"title": "Organización Panamericana de la Salud", "publisher": "OPS/OMS", "url": "https://www.paho.org/es", "use": "Salud en las Américas"}, {"title": "Organización Mundial de la Salud", "publisher": "OMS", "url": "https://www.who.int/es", "use": "Información de salud mundial"}, {"title": "Ministerio de Salud y Protección Social", "publisher": "Gobierno de Colombia", "url": "https://www.minsalud.gov.co/", "use": "Normas y programas de salud en Colombia"}]'::jsonb, null),
  ('odontologia', 'Odontología (Fundamentos)', 'Salud', '#26A69A', 'Explora la salud bucal: anatomía dental, caries, periodoncia, prevención, especialidades odontológicas y salud oral comunitaria. Curso formativo: no habilita para el ejercicio profesional.', 89900, 5, '[{"title": "Salud bucodental (nota descriptiva)", "publisher": "OMS", "url": "https://www.who.int/es/news-room/fact-sheets/detail/oral-health", "use": "Salud oral en el mundo"}, {"title": "Ministerio de Salud y Protección Social", "publisher": "Gobierno de Colombia", "url": "https://www.minsalud.gov.co/", "use": "Normas y programas de salud en Colombia"}]'::jsonb, null),
  ('farmacia', 'Farmacia (Fundamentos)', 'Salud', '#6A1B9A', 'Aprende sobre medicamentos: química farmacéutica, farmacología, formas farmacéuticas, dispensación, atención farmacéutica, regulación y farmacovigilancia. Curso formativo: no habilita para el ejercicio profesional.', 89900, 5, '[{"title": "INVIMA", "publisher": "Instituto Nacional de Vigilancia de Medicamentos y Alimentos", "url": "https://www.invima.gov.co/", "use": "Medicamentos, dispositivos y alimentos"}, {"title": "Resistencia a los antimicrobianos", "publisher": "OMS", "url": "https://www.who.int/es/news-room/fact-sheets/detail/antimicrobial-resistance", "use": "Uso responsable de antibióticos"}, {"title": "MedlinePlus en español", "publisher": "Biblioteca Nacional de Medicina de EE. UU.", "url": "https://medlineplus.gov/spanish/", "use": "Información de salud para pacientes"}]'::jsonb, null),
  ('nutricion-y-dietetica', 'Nutrición y Dietética', 'Salud', '#7CB342', 'Comprende la alimentación y la nutrición: nutrientes, evaluación nutricional, ciclo vital, nutrición clínica, deporte, inocuidad y salud pública. Curso formativo: no habilita para el ejercicio profesional.', 89900, 5, '[{"title": "Guías alimentarias basadas en alimentos para Colombia", "publisher": "FAO", "url": "https://www.fao.org/nutrition/education/dietary-guidelines/regions/colombia/en/", "use": "Guías alimentarias oficiales"}, {"title": "Alimentación saludable (nota descriptiva)", "publisher": "OMS", "url": "https://www.who.int/es/news-room/fact-sheets/detail/healthy-diet", "use": "Recomendaciones de alimentación"}, {"title": "ICBF", "publisher": "Instituto Colombiano de Bienestar Familiar", "url": "https://www.icbf.gov.co/", "use": "Primera infancia y protección"}]'::jsonb, null),
