  ('entrenamiento-deportivo', 'Entrenamiento Deportivo', 'Salud y deporte', '#D84315', 'Dirige el entrenamiento de deportistas y equipos: planificación, periodización, técnica, táctica, formación de talentos y dirección en competencia.', 89900, 5, '[{"title": "Ministerio del Deporte", "publisher": "Gobierno de Colombia", "url": "https://www.mindeporte.gov.co/", "use": "Sistema Nacional del Deporte"}, {"title": "American College of Sports Medicine", "publisher": "ACSM", "url": "https://www.acsm.org/", "use": "Ciencia del ejercicio y certificaciones"}, {"title": "Comité Olímpico Colombiano", "publisher": "COC", "url": "https://olimpicocol.co/", "use": "Deporte olímpico en Colombia"}]'::jsonb, null),
  ('preparacion-fisica', 'Preparación Física', 'Salud y deporte', '#BF360C', 'Desarrolla las capacidades físicas del deportista: fuerza, potencia, velocidad, resistencia, movilidad, prevención de lesiones y readaptación.', 89900, 5, '[{"title": "National Strength and Conditioning Association", "publisher": "NSCA", "url": "https://www.nsca.com/", "use": "Fuerza y acondicionamiento"}, {"title": "American College of Sports Medicine", "publisher": "ACSM", "url": "https://www.acsm.org/", "use": "Ciencia del ejercicio y certificaciones"}]'::jsonb, null),
  ('gestion-deportiva', 'Gestión Deportiva', 'Salud y deporte', '#1565C0', 'Administra organizaciones y eventos deportivos: sistema deportivo, clubes, marketing, patrocinio, finanzas, instalaciones y legislación del deporte.', 89900, 5, '[{"title": "Ley 181 de 1995 (Ley del Deporte)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0181_1995.html", "use": "Marco legal del deporte y la recreación"}, {"title": "Ministerio del Deporte", "publisher": "Gobierno de Colombia", "url": "https://www.mindeporte.gov.co/", "use": "Sistema Nacional del Deporte"}, {"title": "Comité Olímpico Colombiano", "publisher": "COC", "url": "https://olimpicocol.co/", "use": "Deporte olímpico en Colombia"}]'::jsonb, null),
  ('fisiologia-del-ejercicio', 'Fisiología del Ejercicio', 'Salud y deporte', '#C2185B', 'Entiende cómo responde y se adapta el cuerpo al ejercicio: bioenergética, sistemas cardiorrespiratorio y neuromuscular, ambiente, salud y evaluación.', 89900, 5, '[{"title": "American College of Sports Medicine", "publisher": "ACSM", "url": "https://www.acsm.org/", "use": "Ciencia del ejercicio y certificaciones"}, {"title": "Actividad física (nota descriptiva)", "publisher": "OMS", "url": "https://www.who.int/es/news-room/fact-sheets/detail/physical-activity", "use": "Recomendaciones de actividad física"}, {"title": "Physical Activity Guidelines for Americans", "publisher": "U.S. Department of Health and Human Services", "url": "https://odphp.health.gov/our-work/nutrition-physical-activity/physical-activity-guidelines", "use": "Guías de actividad física"}]'::jsonb, null),
  ('biomecanica-deportiva', 'Biomecánica Deportiva', 'Salud y deporte', '#00838F', 'Analiza el movimiento deportivo con física: cinemática, cinética, análisis de video, sensores, técnica por deporte, equipamiento y prevención de lesiones.', 89900, 5, '[{"title": "International Society of Biomechanics in Sports", "publisher": "ISBS", "url": "https://isbs.org/", "use": "Investigación en biomecánica deportiva"}, {"title": "Física universitaria volumen 1 (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/f%C3%ADsica-universitaria-volumen-1", "use": "Mecánica y física para ingenieros"}, {"title": "Simulaciones PhET", "publisher": "Universidad de Colorado Boulder", "url": "https://phet.colorado.edu/es/", "use": "Simulaciones interactivas"}]'::jsonb, null),
  ('recreacion', 'Recreación', 'Salud y deporte', '#FB8C00', 'Diseña experiencias de ocio y tiempo libre: juego, animación, campamentos, recreación comunitaria, inclusiva, ecológica y gestión de programas recreativos.', 89900, 5, '[{"title": "Ley 181 de 1995 (Ley del Deporte)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0181_1995.html", "use": "Marco legal del deporte y la recreación"}, {"title": "Ministerio del Deporte", "publisher": "Gobierno de Colombia", "url": "https://www.mindeporte.gov.co/", "use": "Sistema Nacional del Deporte"}]'::jsonb, null),
  ('entrenamiento-personal', 'Entrenamiento Personal', 'Salud y deporte', '#6A1B9A', 'Prepárate para trabajar como entrenador personal: evaluación de clientes, diseño de programas, coaching de hábitos, poblaciones especiales y negocio fitness.', 89900, 5, '[{"title": "American College of Sports Medicine", "publisher": "ACSM", "url": "https://www.acsm.org/", "use": "Ciencia del ejercicio y certificaciones"}, {"title": "National Strength and Conditioning Association", "publisher": "NSCA", "url": "https://www.nsca.com/", "use": "Fuerza y acondicionamiento"}, {"title": "Actividad física (nota descriptiva)", "publisher": "OMS", "url": "https://www.who.int/es/news-room/fact-sheets/detail/physical-activity", "use": "Recomendaciones de actividad física"}]'::jsonb, null),
  ('desarrollo-de-software', 'Desarrollo de Software (Full Stack)', 'Tecnología', '#3F51B5', 'Construye aplicaciones web completas: HTML, CSS, JavaScript, TypeScript, React, APIs con Python, bases de datos, pruebas y despliegue.', 89900, 5, '[{"title": "Aprende desarrollo web", "publisher": "MDN Web Docs – Mozilla", "url": "https://developer.mozilla.org/es/docs/Learn_web_development", "use": "HTML, CSS y JavaScript"}, {"title": "Aprende React", "publisher": "Meta – React", "url": "https://es.react.dev/learn", "use": "Interfaces con React"}, {"title": "Documentación de FastAPI", "publisher": "FastAPI", "url": "https://fastapi.tiangolo.com/es/", "use": "APIs con Python"}]'::jsonb, null),
  ('ciberseguridad', 'Ciberseguridad', 'Tecnología', '#B71C1C', 'Protege sistemas y datos: fundamentos de seguridad, redes seguras, criptografía, gestión de vulnerabilidades, respuesta a incidentes y normativa.', 89900, 5, '[{"title": "Marco de Ciberseguridad del NIST", "publisher": "NIST", "url": "https://www.nist.gov/cyberframework", "use": "Gestión de la ciberseguridad"}, {"title": "OWASP Top 10", "publisher": "OWASP Foundation", "url": "https://owasp.org/www-project-top-ten/", "use": "Riesgos de seguridad en aplicaciones"}, {"title": "ColCERT", "publisher": "Grupo de Respuesta a Emergencias Cibernéticas de Colombia", "url": "https://www.colcert.gov.co/", "use": "Alertas e incidentes en Colombia"}, {"title": "Ley 1273 de 2009 (delitos informáticos)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1273_2009.html", "use": "Delitos informáticos en Colombia"}]'::jsonb, null),
  ('redes-y-telecomunicaciones', 'Redes y Telecomunicaciones', 'Tecnología', '#0288D1', 'Instala y administra redes en la práctica: cableado, direccionamiento IP, switching, routing, Wi-Fi, servicios de red, seguridad y diagnóstico.', 89900, 5, '[{"title": "Cisco Networking Academy", "publisher": "Cisco", "url": "https://www.netacad.com/", "use": "Cursos de redes"}, {"title": "Documentación de Wireshark", "publisher": "Wireshark Foundation", "url": "https://www.wireshark.org/docs/", "use": "Análisis de tráfico"}, {"title": "Ministerio TIC", "publisher": "Gobierno de Colombia", "url": "https://www.mintic.gov.co/portal/inicio/", "use": "Políticas de tecnología y telecomunicaciones"}]'::jsonb, null),
  ('internet-de-las-cosas', 'Internet de las Cosas (IoT)', 'Tecnología', '#00897B', 'Conecta objetos a internet: sensores, microcontroladores, protocolos de comunicación, plataformas en la nube, análisis de datos y seguridad IoT.', 89900, 5, '[{"title": "Documentación de Arduino", "publisher": "Arduino", "url": "https://docs.arduino.cc/", "use": "Microcontroladores y prototipos"}, {"title": "ESP-IDF para ESP32", "publisher": "Espressif Systems", "url": "https://docs.espressif.com/projects/esp-idf/en/latest/esp32/", "use": "Programación de ESP32"}, {"title": "MQTT", "publisher": "OASIS / mqtt.org", "url": "https://mqtt.org/", "use": "Protocolo de mensajería IoT"}]'::jsonb, null),
  ('computacion-forense', 'Computación Forense', 'Tecnología', '#37474F', 'Investiga incidentes digitales con rigor: evidencia digital, cadena de custodia, adquisición, análisis de sistemas, redes y móviles, e informes periciales.', 89900, 5, '[{"title": "NIST SP 800-86: técnicas forenses en respuesta a incidentes", "publisher": "NIST", "url": "https://csrc.nist.gov/pubs/sp/800/86/final", "use": "Metodología forense"}, {"title": "Ley 1273 de 2009 (delitos informáticos)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1273_2009.html", "use": "Delitos informáticos en Colombia"}, {"title": "Ley 1581 de 2012 (protección de datos personales)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1581_2012.html", "use": "Protección de datos personales"}]'::jsonb, null),
  ('administracion-de-sistemas', 'Administración de Sistemas', 'Tecnología', '#455A64', 'Mantén servidores y servicios funcionando: Linux y Windows Server, usuarios, almacenamiento, servicios, automatización, respaldos, monitoreo y nube.', 89900, 5, '[{"title": "Documentación de Ubuntu Server", "publisher": "Canonical", "url": "https://ubuntu.com/server/docs/", "use": "Servidores Linux"}, {"title": "Documentación de Windows Server", "publisher": "Microsoft Learn", "url": "https://learn.microsoft.com/es-es/windows-server/", "use": "Servidores Windows"}, {"title": "Documentación de Kubernetes", "publisher": "The Linux Foundation – CNCF", "url": "https://kubernetes.io/es/docs/home/", "use": "Orquestación de contenedores"}]'::jsonb, null),
  ('desarrollo-de-aplicaciones-moviles', 'Desarrollo de Aplicaciones Móviles', 'Tecnología', '#43A047', 'Crea apps para Android e iOS: diseño móvil, Kotlin, Swift, React Native y Flutter, datos, APIs, notificaciones, pruebas y publicación en tiendas.', 89900, 5, '[{"title": "Android Developers", "publisher": "Google", "url": "https://developer.android.com/", "use": "Desarrollo Android"}, {"title": "Apple Developer Documentation", "publisher": "Apple", "url": "https://developer.apple.com/documentation/", "use": "Desarrollo iOS"}, {"title": "Documentación de Flutter", "publisher": "Google", "url": "https://docs.flutter.dev/", "use": "Apps multiplataforma"}, {"title": "Material Design 3", "publisher": "Google", "url": "https://m3.material.io/", "use": "Diseño de interfaces"}]'::jsonb, null),
  ('realidad-virtual-y-aumentada', 'Realidad Virtual y Aumentada', 'Tecnología', '#8E24AA', 'Crea experiencias inmersivas: fundamentos XR, modelado 3D, Unity, interacción, realidad aumentada móvil, WebXR, diseño de experiencias y aplicaciones.', 89900, 5, '[{"title": "Unity Learn", "publisher": "Unity Technologies", "url": "https://learn.unity.com/", "use": "Desarrollo 3D, VR y AR"}, {"title": "WebXR – Immersive Web", "publisher": "W3C Immersive Web", "url": "https://immersiveweb.dev/", "use": "Realidad extendida en el navegador"}, {"title": "Blender", "publisher": "Blender Foundation", "url": "https://www.blender.org/", "use": "Modelado y animación 3D gratuitos"}]'::jsonb, null),
  ('devops', 'DevOps', 'Tecnología', '#00796B', 'Une desarrollo y operaciones: cultura DevOps, Git, CI/CD, contenedores, Kubernetes, infraestructura como código, observabilidad y DevSecOps.', 89900, 5, '[{"title": "Documentación de Docker", "publisher": "Docker", "url": "https://docs.docker.com/", "use": "Contenedores"}, {"title": "Documentación de Kubernetes", "publisher": "The Linux Foundation – CNCF", "url": "https://kubernetes.io/es/docs/home/", "use": "Orquestación de contenedores"}, {"title": "Documentación de Terraform", "publisher": "HashiCorp", "url": "https://developer.hashicorp.com/terraform/docs", "use": "Infraestructura como código"}, {"title": "Pro Git (libro gratuito en español)", "publisher": "Git", "url": "https://git-scm.com/book/es/v2", "use": "Control de versiones"}]'::jsonb, null),
  ('automatizacion-industrial', 'Automatización Industrial', 'Tecnología', '#F57F17', 'Automatiza procesos de planta: sensores, neumática, PLC, HMI, SCADA, redes industriales, variadores, robótica, seguridad de máquinas e Industria 4.0.', 89900, 5, '[{"title": "PLCopen", "publisher": "PLCopen", "url": "https://plcopen.org/", "use": "Programación de PLC (IEC 61131-3)"}, {"title": "OPC Foundation", "publisher": "OPC Foundation", "url": "https://opcfoundation.org/", "use": "Comunicación industrial OPC UA"}, {"title": "International Federation of Robotics", "publisher": "IFR", "url": "https://ifr.org/", "use": "Estadísticas y tendencias de robótica"}]'::jsonb, null),
  ('blockchain', 'Blockchain', 'Tecnología', '#FF8F00', 'Comprende y construye con blockchain: criptografía, consenso, Bitcoin, Ethereum, contratos inteligentes, aplicaciones descentralizadas, casos de uso y regulación.', 89900, 5, '[{"title": "Bitcoin: A Peer-to-Peer Electronic Cash System", "publisher": "Satoshi Nakamoto", "url": "https://bitcoin.org/bitcoin.pdf", "use": "Documento original de Bitcoin"}, {"title": "Documentación de desarrollo de Ethereum", "publisher": "ethereum.org", "url": "https://ethereum.org/es/developers/docs/", "use": "Contratos inteligentes"}, {"title": "Superintendencia Financiera de Colombia", "publisher": "Gobierno de Colombia", "url": "https://www.superfinanciera.gov.co/", "use": "Sistema financiero y protección al consumidor"}]'::jsonb, null),
  ('soporte-tecnico', 'Soporte Técnico', 'Tecnología', '#5C6BC0', 'Resuelve problemas de TI con método: hardware, sistemas operativos, redes, impresoras, seguridad básica, mesa de ayuda, ITIL y atención al usuario.', 89900, 5, '[{"title": "Soporte técnico de Microsoft", "publisher": "Microsoft", "url": "https://support.microsoft.com/es-es", "use": "Solución de problemas de Windows y Office"}, {"title": "Documentación de Windows", "publisher": "Microsoft Learn", "url": "https://learn.microsoft.com/es-es/windows/", "use": "Administración de equipos"}, {"title": "Certificaciones ITIL", "publisher": "PeopleCert", "url": "https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1", "use": "Gestión de servicios de TI"}]'::jsonb, null),
  ('sistemas-de-informacion', 'Sistemas de Información', 'Tecnología', '#00695C', 'Usa la información como recurso estratégico: tipos de sistemas, ERP, CRM, análisis de requisitos, procesos, datos, gobierno de TI y transformación digital.', 89900, 5, '[{"title": "COBIT", "publisher": "ISACA", "url": "https://www.isaca.org/resources/cobit", "use": "Gobierno de TI"}, {"title": "Especificación BPMN", "publisher": "Object Management Group", "url": "https://www.bpmn.org/", "use": "Modelado de procesos"}, {"title": "Ministerio TIC", "publisher": "Gobierno de Colombia", "url": "https://www.mintic.gov.co/portal/inicio/", "use": "Políticas de tecnología y telecomunicaciones"}]'::jsonb, null)
